  1→import {
  2→  createContext,
  3→  useCallback,
  4→  useRef,
  5→  useState,
  6→  type ReactNode,
  7→} from 'react';
  8→import { runAgentLoop, runAgentEditLoop } from './agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from './types';
 10→
 11→interface AgentContextValue {
 12→  messages: ChatMessage[];
 13→  isStreaming: boolean;
 14→  sendMessage: (text: string) => void;
 15→  editMessage: (messageIndex: number, newContent: string) => void;
 16→  deleteMessage: (messageIndex: number) => void;
 17→  clearMessages: () => void;
 18→}
 19→
 20→export const AgentContext = createContext<AgentContextValue>({
 21→  messages: [],
 22→  isStreaming: false,
 23→  sendMessage: () => {},
 24→  editMessage: () => {},
 25→  deleteMessage: () => {},
 26→  clearMessages: () => {},
 27→});
 28→
 29→function generateId() {
 30→  return Math.random().toString(36).slice(2, 10);
 31→}
 32→
 33→export function AgentProvider({
 34→  children,
 35→  refreshTables,
 36→}: {
 37→  children: ReactNode;
 38→  refreshTables: () => Promise<void>;
 39→}) {
 40→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 41→  const [isStreaming, setIsStreaming] = useState(false);
 42→  const abortRef = useRef<AbortController | null>(null);
 43→  const textBufferRef = useRef('');
 44→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 45→  const assistantIdRef = useRef('');
 46→  const segmentsRef = useRef<ContentSegment[]>([]);
 47→  const currentTextRef = useRef('');
 48→  const sessionIdRef = useRef<string | null>(null);
 49→
 50→  const flushText = useCallback(() => {
 51→    const text = textBufferRef.current;
 52→    if (!text) return;
 53→    const id = assistantIdRef.current;
 54→    currentTextRef.current += text;
 55→    setMessages((prev) =>
 56→      prev.map((m) =>
 57→        m.id === id ? { ...m, content: m.content + text } : m
 58→      )
 59→    );
 60→    textBufferRef.current = '';
 61→  }, []);
 62→
 63→  const sendMessage = useCallback(
 64→    async (text: string) => {
 65→      if (isStreaming) return;
 66→
 67→      const userMsg: ChatMessage = {
 68→        id: generateId(),
 69→        role: 'user',
 70→        content: text,
 71→      };
 72→
 73→      const assistantId = generateId();
 74→      assistantIdRef.current = assistantId;
 75→      const assistantMsg: ChatMessage = {
 76→        id: assistantId,
 77→        role: 'assistant',
 78→        content: '',
 79→        toolCalls: [],
 80→        isStreaming: true,
 81→      };
 82→
 83→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 84→      setIsStreaming(true);
 85→      textBufferRef.current = '';
 86→      segmentsRef.current = [];
 87→      currentTextRef.current = '';
 88→
 89→      const controller = new AbortController();
 90→      abortRef.current = controller;
 91→
 92→      await runAgentLoop(
 93→        text,
 94→        sessionIdRef.current,
 95→        {
 96→          onTextChunk: (chunk) => {
 97→            textBufferRef.current += chunk;
 98→            if (!flushTimerRef.current) {
 99→              flushTimerRef.current = setTimeout(() => {
100→                flushText();
101→                flushTimerRef.current = null;
102→              }, 50);
103→            }
104→          },
105→          onThinkingDone: () => {
106→            // Extended thinking just ended and a text block is starting.
107→            // Create a thinking segment from accumulated thinking text.
108→            if (flushTimerRef.current) {
109→              clearTimeout(flushTimerRef.current);
110→              flushTimerRef.current = null;
111→            }
112→            flushText();
113→            if (currentTextRef.current.trim()) {
114→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
115→              currentTextRef.current = '';
116→            }
117→            setMessages((prev) =>
118→              prev.map((m) =>
119→                m.id === assistantId
120→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
121→                  : m
122→              )
123→            );
124→          },
125→          onToolCall: (pending: ToolCallResult) => {
126→            if (flushTimerRef.current) {
127→              clearTimeout(flushTimerRef.current);
128→              flushTimerRef.current = null;
129→            }
130→            flushText();
131→            if (currentTextRef.current.trim()) {
132→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
133→              currentTextRef.current = '';
134→            }
135→            // Add a pending tool segment so the input is shown immediately
136→            segmentsRef.current.push({
137→              type: 'tool',
138→              toolResult: pending,
139→            });
140→            setMessages((prev) =>
141→              prev.map((m) =>
142→                m.id === assistantId
143→                  ? { ...m, segments: [...segmentsRef.current] }
144→                  : m
145→              )
146→            );
147→          },
148→          onToolResult: (result: ToolCallResult) => {
149→            // Merge result into pending tool segment (keep input info, add output)
150→            const pendingIdx = segmentsRef.current.findIndex(
151→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
152→            );
153→            if (pendingIdx !== -1) {
154→              const pending = segmentsRef.current[pendingIdx].toolResult!;
155→              segmentsRef.current[pendingIdx] = {
156→                type: 'tool',
157→                toolResult: {
158→                  ...pending,
159→                  ...result,
160→                  toolName: result.toolName || pending.toolName,
161→                  command: result.command || pending.command,
162→                  toolInput: result.toolInput || pending.toolInput,
163→                },
164→              };
165→            } else {
166→              segmentsRef.current.push({ type: 'tool', toolResult: result });
167→            }
168→            setMessages((prev) =>
169→              prev.map((m) =>
170→                m.id === assistantId
171→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
172→                  : m
173→              )
174→            );
175→            refreshTables();
176→          },
177→          onDone: (newSessionId) => {
178→            if (newSessionId) sessionIdRef.current = newSessionId;
179→            if (flushTimerRef.current) {
180→              clearTimeout(flushTimerRef.current);
181→              flushTimerRef.current = null;
182→            }
183→            flushText();
184→            if (currentTextRef.current.trim()) {
185→              segmentsRef.current.push({
186→                type: 'answer',
187→                text: currentTextRef.current,
188→              });
189→              currentTextRef.current = '';
190→            }
191→            setMessages((prev) =>
192→              prev.map((m) =>
193→                m.id === assistantId
194→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
195→                  : m
196→              )
197→            );
198→            setIsStreaming(false);
199→            abortRef.current = null;
200→          },
201→          onError: (error) => {
202→            if (flushTimerRef.current) {
203→              clearTimeout(flushTimerRef.current);
204→              flushTimerRef.current = null;
205→            }
206→            flushText();
207→            setMessages((prev) =>
208→              prev.map((m) =>
209→                m.id === assistantId
210→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
211→                  : m
212→              )
213→            );
214→            setIsStreaming(false);
215→            abortRef.current = null;
216→          },
217→        },
218→        controller.signal
219→      );
220→    },
221→    [isStreaming, flushText, refreshTables]
222→  );
223→
224→  const editMessage = useCallback(
225→    async (messageIndex: number, newContent: string) => {
226→      if (isStreaming) return;
227→
228→      // Build conversation history from messages before the edit point
229→      const conversationHistory: { role: string; content: string }[] = [];
230→      for (let i = 0; i < messageIndex; i++) {
231→        const msg = messages[i];
232→        if (msg.role === 'user' || msg.role === 'assistant') {
233→          conversationHistory.push({ role: msg.role, content: msg.content });
234→        }
235→      }
236→
237→      const assistantId = generateId();
238→      assistantIdRef.current = assistantId;
239→
240→      const userMsg: ChatMessage = {
241→        id: generateId(),
242→        role: 'user',
243→        content: newContent,
244→      };
245→      const assistantMsg: ChatMessage = {
246→        id: assistantId,
247→        role: 'assistant',
248→        content: '',
249→        toolCalls: [],
250→        isStreaming: true,
251→      };
252→
253→      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
254→      setIsStreaming(true);
255→      textBufferRef.current = '';
256→      segmentsRef.current = [];
257→      currentTextRef.current = '';
258→
259→      const controller = new AbortController();
260→      abortRef.current = controller;
261→
262→      await runAgentEditLoop(
263→        newContent,
264→        conversationHistory,
265→        {
266→          onTextChunk: (chunk) => {
267→            textBufferRef.current += chunk;
268→            if (!flushTimerRef.current) {
269→              flushTimerRef.current = setTimeout(() => {
270→                flushText();
271→                flushTimerRef.current = null;
272→              }, 50);
273→            }
274→          },
275→          onThinkingDone: () => {
276→            if (flushTimerRef.current) {
277→              clearTimeout(flushTimerRef.current);
278→              flushTimerRef.current = null;
279→            }
280→            flushText();
281→            if (currentTextRef.current.trim()) {
282→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
283→              currentTextRef.current = '';
284→            }
285→            setMessages((prev) =>
286→              prev.map((m) =>
287→                m.id === assistantId
288→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
289→                  : m
290→              )
291→            );
292→          },
293→          onToolCall: (pending: ToolCallResult) => {
294→            if (flushTimerRef.current) {
295→              clearTimeout(flushTimerRef.current);
296→              flushTimerRef.current = null;
297→            }
298→            flushText();
299→            if (currentTextRef.current.trim()) {
300→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
301→              currentTextRef.current = '';
302→            }
303→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
304→            setMessages((prev) =>
305→              prev.map((m) =>
306→                m.id === assistantId
307→                  ? { ...m, segments: [...segmentsRef.current] }
308→                  : m
309→              )
310→            );
311→          },
312→          onToolResult: (result: ToolCallResult) => {
313→            const pendingIdx = segmentsRef.current.findIndex(
314→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
315→            );
316→            if (pendingIdx !== -1) {
317→              const pending = segmentsRef.current[pendingIdx].toolResult!;
318→              segmentsRef.current[pendingIdx] = {
319→                type: 'tool',
320→                toolResult: {
321→                  ...pending,
322→                  ...result,
323→                  toolName: result.toolName || pending.toolName,
324→                  command: result.command || pending.command,
325→                  toolInput: result.toolInput || pending.toolInput,
326→                },
327→              };
328→            } else {
329→              segmentsRef.current.push({ type: 'tool', toolResult: result });
330→            }
331→            setMessages((prev) =>
332→              prev.map((m) =>
333→                m.id === assistantId
334→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
335→                  : m
336→              )
337→            );
338→            refreshTables();
339→          },
340→          onDone: (newSessionId) => {
341→            if (newSessionId) sessionIdRef.current = newSessionId;
342→            if (flushTimerRef.current) {
343→              clearTimeout(flushTimerRef.current);
344→              flushTimerRef.current = null;
345→            }
346→            flushText();
347→            if (currentTextRef.current.trim()) {
348→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
349→              currentTextRef.current = '';
350→            }
351→            setMessages((prev) =>
352→              prev.map((m) =>
353→                m.id === assistantId
354→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
355→                  : m
356→              )
357→            );
358→            setIsStreaming(false);
359→            abortRef.current = null;
360→          },
361→          onError: (error) => {
362→            if (flushTimerRef.current) {
363→              clearTimeout(flushTimerRef.current);
364→              flushTimerRef.current = null;
365→            }
366→            flushText();
367→            setMessages((prev) =>
368→              prev.map((m) =>
369→                m.id === assistantId
370→                  ? { ...m, content: m.content + `\n\n**Error:** ${error}`, isStreaming: false }
371→                  : m
372→              )
373→            );
374→            setIsStreaming(false);
375→            abortRef.current = null;
376→          },
377→        },
378→        controller.signal
379→      );
380→    },
381→    [isStreaming, messages, flushText, refreshTables]
382→  );
383→
384→  const deleteMessage = useCallback(
385→    (messageIndex: number) => {
386→      if (isStreaming) return;
387→
388→      setMessages((prev) => prev.slice(0, messageIndex));
389→
390→      // Clear session so next message starts fresh
391→      sessionIdRef.current = null;
392→    },
393→    [isStreaming]
394→  );
395→
396→  const clearMessages = useCallback(() => {
397→    if (abortRef.current) {
398→      abortRef.current.abort();
399→    }
400→    setMessages([]);
401→    setIsStreaming(false);
402→    sessionIdRef.current = null;
403→  }, []);
404→
405→  return (
406→    <AgentContext.Provider
407→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages }}
408→    >
409→      {children}
410→    </AgentContext.Provider>
411→  );
412→}
