 1→import { useState, useRef } from 'react';
 2→import { useAgent } from '../useAgent';
 3→import './ChatInput.css';
 4→
 5→export function ChatInput() {
 6→  const { sendMessage, isStreaming } = useAgent();
 7→  const [text, setText] = useState('');
 8→  const textareaRef = useRef<HTMLTextAreaElement>(null);
 9→
10→  const handleSend = () => {
11→    const trimmed = text.trim();
12→    if (!trimmed || isStreaming) return;
13→    sendMessage(trimmed);
14→    setText('');
15→    if (textareaRef.current) {
16→      textareaRef.current.style.height = 'auto';
17→    }
18→  };
19→
20→  const handleKeyDown = (e: React.KeyboardEvent) => {
21→    if (e.key === 'Enter' && !e.shiftKey) {
22→      e.preventDefault();
23→      handleSend();
24→    }
25→  };
26→
27→  const handleInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
28→    setText(e.target.value);
29→    const el = e.target;
30→    el.style.height = 'auto';
31→    el.style.height = Math.min(el.scrollHeight, 150) + 'px';
32→  };
33→
34→  return (
35→    <div className="chat-input">
36→      <textarea
37→        ref={textareaRef}
38→        className="chat-input__textarea"
39→        value={text}
40→        onChange={handleInput}
41→        onKeyDown={handleKeyDown}
42→        placeholder={isStreaming ? 'Waiting for response...' : 'Ask about your data...'}
43→        disabled={isStreaming}
44→        rows={1}
45→      />
46→      <button
47→        className="chat-input__send"
48→        onClick={handleSend}
49→        disabled={isStreaming || !text.trim()}
50→      >
51→        Send
52→      </button>
53→    </div>
54→  );
55→}
